import React from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";

const labels = {
  dashboard: "Overview",
  reports: "Reports queue",
  analytics: "Analytics",
  officers: "Officers",
};

const TopHeader = ({ onMenu, notify }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const page = location.pathname.split("/")[1] || "dashboard";

  return (
    <header className="sticky top-0 z-20 flex h-[62px] items-center justify-between border-b border-gray-100 bg-white px-4 sm:px-6 lg:px-9">
      <div className="flex min-w-0 items-center">
        <button
          aria-label="Open menu"
          className="mr-3 text-lg text-gray-600 lg:hidden"
          onClick={onMenu}
        >
          ☰
        </button>
        <div className="truncate text-[11px] text-gray-400">
          <Link to="/dashboard" className="hover:text-[#185835]">
            Workspace
          </Link>
          <span className="px-2 text-gray-300">/</span>
          <b className="text-gray-800">{labels[page] || "Case details"}</b>
        </div>
      </div>

      <div className="ml-3 flex shrink-0 items-center gap-3 sm:gap-5">
        <span className="hidden items-center gap-2 text-[10px] text-gray-500 sm:flex">
          <i className="h-1.5 w-1.5 rounded-full bg-green-500 ring-4 ring-green-50" />
          Live updates
        </span>
        <button
          aria-label="Notifications"
          className="relative text-lg text-gray-500"
          onClick={() => notify("You’re all caught up")}
        >
          ♧<i className="absolute right-0 top-0 h-1.5 w-1.5 rounded-full bg-orange-400" />
        </button>
        <span className="hidden h-6 border-l border-gray-200 sm:block" />
        <button
          className="flex items-center gap-2 text-[11px] text-gray-700"
          onClick={() => navigate("/login")}
        >
          <span className="grid h-7 w-7 place-items-center rounded-full bg-[#e5e8d9] text-[9px] font-bold text-[#526c46]">
            TK
          </span>
          <span className="hidden sm:inline">Thoko Kalua</span>
          <span>⌄</span>
        </button>
      </div>
    </header>
  );
};

export default TopHeader;
